const { useLayoutEffect, useRef, useState } = React;

const INITIAL = "#8a8f98";
const MODES = [
  { value: "plain", label: "未注册", name: "--cb-inh-plain" },
  { value: "on", label: "inherits: true", name: "--cb-inh-on" },
  { value: "off", label: "inherits: false", name: "--cb-inh-off" },
];
const PARENT_COLORS = [
  { token: "tag-1", value: "var(--tau-tag-1)", swatch: "bg-tag-1" },
  { token: "tag-3", value: "var(--tau-tag-3)", swatch: "bg-tag-3" },
  { token: "tag-5", value: "var(--tau-tag-5)", swatch: "bg-tag-5" },
];
const LEVELS = ["parent", "child", "grandchild"];

const STYLE = `
  @scope {
    .cb-swatch { box-shadow: inset 0 0 0 1px var(--tau-line-1); }
  }
  @property --cb-inh-on {
    syntax: "<color>";
    inherits: true;
    initial-value: ${INITIAL};
  }
  @property --cb-inh-off {
    syntax: "<color>";
    inherits: false;
    initial-value: ${INITIAL};
  }
`;

const ruleLines = mode =>
  mode.value === "plain"
    ? ["/* 未注册，普通自定义属性总是继承 */"]
    : [
        `@property ${mode.name} {`,
        `  syntax: "<color>";`,
        `  inherits: ${mode.value === "on"};`,
        `  initial-value: ${INITIAL};`,
        "}",
      ];

// 嵌套的一层：左上角色块显示该层 var() 读到的颜色
const Level = ({ name, levelRef, varName, style, children }) => (
  <div ref={levelRef} style={style} className="flex flex-col gap-2 rounded-tau-sm border border-dashed border-line-1 p-2.5">
    <div className="flex items-center gap-2">
      <span className="cb-swatch size-5 shrink-0 rounded-tau-sm" style={{ backgroundColor: `var(${varName})` }} />
      <span className="font-tau-mono text-tau-sm text-ink-2">.{name}</span>
    </div>
    {children}
  </div>
);

const Component = () => {
  const refs = [useRef(null), useRef(null), useRef(null)];
  const [modeValue, setModeValue] = useState("on");
  const [parentColor, setParentColor] = useState(PARENT_COLORS[0]);
  const [computed, setComputed] = useState(["", "", ""]);

  const mode = MODES.find(item => item.value === modeValue);

  // 读出每一层的计算值，对照继承与否
  useLayoutEffect(() => {
    setComputed(refs.map(ref => getComputedStyle(ref.current).getPropertyValue(mode.name).trim()));
  }, [modeValue, parentColor]);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,40%)]">
        <div className="min-w-0 rounded-tau-md border border-line-1 p-3">
          <Level name="parent" levelRef={refs[0]} varName={mode.name} style={{ [mode.name]: parentColor.value }}>
            <Level name="child" levelRef={refs[1]} varName={mode.name}>
              <Level name="grandchild" levelRef={refs[2]} varName={mode.name} />
            </Level>
          </Level>
        </div>
        <div className="flex min-w-0 flex-col gap-3">
          <pre className="m-0 min-w-0 whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
            {ruleLines(mode).join("\n")}
            {"\n.parent { "}
            <span className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {mode.name}: var(--tau-{parentColor.token})
            </span>
            {" }"}
          </pre>
          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
            {LEVELS.map((level, index) => (
              <React.Fragment key={level}>
                <dt className="font-tau-mono text-tau-sm text-ink-3">{level}</dt>
                <dd className="m-0 min-w-0 break-all font-tau-mono text-tau-sm text-ink-1">
                  {index > 0 && modeValue === "off" ? "initial-value" : index > 0 ? "继承 parent" : "自身声明"}
                  {computed[index] && <span className="text-ink-3"> · {computed[index]}</span>}
                </dd>
              </React.Fragment>
            ))}
          </dl>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <ui.RadioGroup label="注册方式" value={modeValue} onValueChange={setModeValue} orientation="horizontal">
          {MODES.map(item => (
            <ui.Radio key={item.value} value={item.value} label={item.label} />
          ))}
        </ui.RadioGroup>
        <div className="flex items-center gap-2">
          <span className="text-tau-sm text-ink-3">parent 取值</span>
          {PARENT_COLORS.map(item => (
            <button
              key={item.token}
              type="button"
              aria-label={item.token}
              aria-pressed={parentColor === item}
              onClick={() => setParentColor(item)}
              className={`size-6 cursor-pointer rounded-full border-2 transition-colors ${item.swatch} ${
                parentColor === item ? "border-ink-1" : "border-transparent"
              }`}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

