const { useLayoutEffect, useRef, useState } = React;

const NAME = "--cb-dup-color";
const RULES = {
  red: { label: "#e8604c", value: "#e8604c" },
  blue: { label: "#3d7be0", value: "#3d7be0" },
};

const ruleText = key => `@property ${NAME} {
  syntax: "<color>";
  inherits: false;
  initial-value: ${RULES[key].value};
}`;

const Component = () => {
  const boxRef = useRef(null);
  const [order, setOrder] = useState(["red", "blue"]);
  const [enabled, setEnabled] = useState({ red: true, blue: true });
  const [computed, setComputed] = useState("");

  const active = order.filter(key => enabled[key]);
  const winner = active[active.length - 1];
  const css = `@scope {}\n${active.map(ruleText).join("\n")}`;

  useLayoutEffect(() => {
    setComputed(getComputedStyle(boxRef.current).getPropertyValue(NAME).trim());
  }, [css]);

  const toggle = key => setEnabled(current => ({ ...current, [key]: !current[key] }));

  return (
    <div className="@container flex flex-col gap-3">
      <style>{css}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(200px,34%)]">
        <ol className="m-0 flex min-w-0 list-none flex-col gap-2 p-0">
          {order.map((key, index) => {
            const isWinner = key === winner;
            return (
              <li
                key={key}
                className={`flex min-w-0 items-start gap-3 rounded-tau-md border p-3 transition-colors ${
                  isWinner ? "border-accent bg-accent-soft" : "border-line-1"
                } ${enabled[key] ? "" : "opacity-50"}`}
              >
                <span className="grid size-5 shrink-0 place-items-center rounded-full bg-hover font-tau-mono text-tau-tiny text-ink-2">
                  {index + 1}
                </span>
                <pre className="m-0 min-w-0 flex-1 whitespace-pre-wrap break-all font-tau-mono text-tau-sm leading-[1.6] text-ink-2">
                  {ruleText(key)}
                </pre>
                <div className="flex shrink-0 flex-col items-end gap-2">
                  <ui.Switch
                    size="sm"
                    checked={enabled[key]}
                    onCheckedChange={() => toggle(key)}
                    aria-label={`启用第 ${index + 1} 条`}
                  />
                  {isWinner && <span className="text-tau-sm text-accent-text">生效</span>}
                </div>
              </li>
            );
          })}
        </ol>
        <div className="flex flex-col items-center justify-center gap-3 rounded-tau-md border border-line-1 p-4">
          <div
            ref={boxRef}
            className="grid size-24 place-items-center rounded-tau-md border border-dashed border-line-1"
            style={{ backgroundColor: `var(${NAME})` }}
          >
            {!winner && <span className="text-tau-sm text-ink-3">无颜色</span>}
          </div>
          <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
            background-color: var({NAME})
          </code>
          <span className="min-w-0 break-all text-center font-tau-mono text-tau-sm text-ink-3">
            {winner ? `initial-value：${RULES[winner].label}` : "未注册，var() 无值，声明无效"}
            {computed && ` · ${computed}`}
          </span>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <ui.Button variant="secondary" size="sm" icon={icons.ArrowDownUp} onClick={() => setOrder(current => [...current].reverse())}>
          交换顺序
        </ui.Button>
        <span className="text-tau-sm text-ink-3">同名注册，后出现的覆盖前面的</span>
      </div>
    </div>
  );
};

