const { useEffect, useRef, useState } = React;

const DISCS = [
  { key: "raw", title: "普通变量", name: "--cb-spin-raw", className: "cb-disc cb-disc-raw" },
  { key: "typed", title: "@property 注册", name: "--cb-spin-typed", className: "cb-disc cb-disc-typed" },
];

const STYLE = `
  @scope {
    .cb-disc {
      border-radius: 9999px;
      box-shadow: inset 0 0 0 1px var(--tau-line-1);
      transition-timing-function: var(--tau-ease-out);
    }
    .cb-disc-raw {
      --cb-spin-raw: 0deg;
      background-image: conic-gradient(from var(--cb-spin-raw), #f06, #9f6, #06f, #f06);
      transition-property: --cb-spin-raw;
    }
    .cb-disc-typed {
      --cb-spin-typed: 0deg;
      background-image: conic-gradient(from var(--cb-spin-typed), #f06, #9f6, #06f, #f06);
      transition-property: --cb-spin-typed;
    }
    .cb-disc-raw[data-on="true"] { --cb-spin-raw: 180deg; }
    .cb-disc-typed[data-on="true"] { --cb-spin-typed: 180deg; }
    .cb-range { accent-color: var(--tau-accent); }
  }
  @property --cb-spin-typed {
    syntax: "<angle>";
    inherits: false;
    initial-value: 0deg;
  }
`;

const Component = () => {
  const discRefs = useRef({});
  const frameRef = useRef(0);
  const [on, setOn] = useState(false);
  const [duration, setDuration] = useState(1.5);
  const [angles, setAngles] = useState({ raw: "0deg", typed: "0deg" });

  // 过渡期间逐帧读取两个变量的计算值，看谁在插值、谁直接跳变
  useEffect(() => {
    const read = () =>
      setAngles(
        Object.fromEntries(
          DISCS.map(disc => [disc.key, getComputedStyle(discRefs.current[disc.key]).getPropertyValue(disc.name).trim() || "0deg"])
        )
      );
    let start = 0;
    const tick = now => {
      start ||= now;
      read();
      if (now - start < duration * 1000 + 150) frameRef.current = requestAnimationFrame(tick);
    };
    frameRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameRef.current);
  }, [on]);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @md:grid-cols-2">
        {DISCS.map(disc => {
          const degrees = parseFloat(angles[disc.key]) || 0;
          return (
            <div key={disc.key} className="flex min-w-0 flex-col items-center gap-3 rounded-tau-md border border-line-1 p-4">
              <span className="text-tau-body text-ink-1">{disc.title}</span>
              <div
                ref={element => {
                  discRefs.current[disc.key] = element;
                }}
                data-on={on}
                className={`size-32 ${disc.className}`}
                style={{ transitionDuration: `${duration}s` }}
              />
              <div className="flex w-full flex-col gap-1.5">
                <div className="flex items-baseline justify-between gap-2">
                  <code className="min-w-0 truncate font-tau-mono text-tau-sm text-ink-3">{disc.name}</code>
                  <span className="font-tau-mono text-tau-sm text-ink-1">{Math.round(degrees)}deg</span>
                </div>
                <div className="h-1.5 overflow-hidden rounded-full bg-hover">
                  <div className="h-full rounded-full bg-accent" style={{ width: `${(degrees / 180) * 100}%` }} />
                </div>
              </div>
            </div>
          );
        })}
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <ui.Button variant="primary" size="sm" icon={on ? icons.RotateCcw : icons.RotateCw} onClick={() => setOn(value => !value)}>
          {on ? "转回 0deg" : "旋转到 180deg"}
        </ui.Button>
        <label className="flex min-w-[220px] flex-1 items-center gap-3">
          <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">transition</span>
          <input
            type="range"
            min={0.5}
            max={3}
            step={0.5}
            value={duration}
            onChange={event => setDuration(Number(event.target.value))}
            className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
          />
          <span className="w-10 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{duration}s</span>
        </label>
      </div>
    </div>
  );
};

