const { useLayoutEffect, useRef, useState } = React;

const PRESETS = [
  { label: "未设置", value: null },
  { label: "12px", value: "12px" },
  { label: "#3d7be0", value: "#3d7be0" },
  { label: "2em", value: "2em" },
];

const STYLE = `
  @scope {
    .cb-checker {
      background-image: conic-gradient(var(--tau-line-1) 25%, transparent 0 50%, var(--tau-line-1) 0 75%, transparent 0);
      background-size: 16px 16px;
    }
  }
  @property --cb-typed-color {
    syntax: "<color>";
    inherits: false;
    initial-value: orange;
  }
`;

const isColor = value => {
  if (typeof CSS !== "undefined" && typeof CSS.supports === "function") return CSS.supports("color", value);
  return value.startsWith("#");
};

// 两种变量在三种情形下的结果，tone 决定结论徽标的状态色
const explain = (registered, value) => {
  if (value === null)
    return registered
      ? { text: "未赋值 → initial-value", tone: "ok" }
      : { text: "变量不存在 → fallback", tone: "ok" };
  if (isColor(value)) return { text: "类型正确 → 使用该值", tone: "ok" };
  return registered
    ? { text: "类型不符，赋值被丢弃 → initial-value", tone: "ok" }
    : { text: "变量存在但类型不对 → 声明无效，transparent", tone: "danger" };
};

const TONE = {
  ok: "bg-ok-soft text-ok",
  danger: "bg-danger-soft text-danger",
};

const BOXES = [
  {
    key: "raw",
    title: "普通变量",
    name: "--cb-raw-color",
    usage: "background-color: var(--cb-raw-color, orange)",
    background: "var(--cb-raw-color, orange)",
    registered: false,
  },
  {
    key: "typed",
    title: "@property <color>",
    name: "--cb-typed-color",
    usage: "background-color: var(--cb-typed-color)",
    background: "var(--cb-typed-color)",
    registered: true,
  },
];

const Component = () => {
  const boxRefs = useRef({});
  const [value, setValue] = useState("12px");
  const [custom, setCustom] = useState("");
  const [computed, setComputed] = useState({});

  const current = custom.trim() || value;

  useLayoutEffect(() => {
    setComputed(Object.fromEntries(BOXES.map(box => [box.key, getComputedStyle(boxRefs.current[box.key]).backgroundColor])));
  }, [current]);

  const choose = next => {
    setCustom("");
    setValue(next);
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @md:grid-cols-2">
        {BOXES.map(box => {
          const result = explain(box.registered, current);
          return (
            <div key={box.key} className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-4">
              <span className="text-tau-body text-ink-1">{box.title}</span>
              <div className="cb-checker overflow-hidden rounded-tau-sm border border-line-1">
                <div
                  ref={element => {
                    boxRefs.current[box.key] = element;
                  }}
                  className="h-20"
                  style={{ [box.name]: current ?? undefined, backgroundColor: box.background }}
                />
              </div>
              <code className="block min-w-0 break-all font-tau-mono text-tau-sm leading-[1.6] text-ink-2">
                {current === null ? `/* 未设置 ${box.name} */` : `${box.name}: ${current};`}
                <br />
                {box.usage};
              </code>
              <span className={`self-start rounded-full px-2.5 py-0.5 text-tau-meta ${TONE[result.tone]}`}>{result.text}</span>
              {computed[box.key] && (
                <span className="min-w-0 break-all font-tau-mono text-tau-sm text-ink-3">计算值：{computed[box.key]}</span>
              )}
            </div>
          );
        })}
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-tau-sm text-ink-3">变量取值</span>
        {PRESETS.map(item => {
          const active = !custom.trim() && value === item.value;
          return (
            <button
              key={item.label}
              type="button"
              aria-pressed={active}
              onClick={() => choose(item.value)}
              className={`cursor-pointer rounded-tau-sm border px-2.5 py-1 font-tau-mono text-tau-sm transition-colors ${
                active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
              }`}
            >
              {item.label}
            </button>
          );
        })}
        <ui.Input
          size="sm"
          clearable
          wrapperClassName="w-[160px]"
          placeholder="自己试一个值"
          aria-label="自定义取值"
          value={custom}
          onChange={event => setCustom(event.target.value)}
        />
      </div>
    </div>
  );
};

